promised = 0        # highest prepare number answered
accepted = None     # (n, v) of highest accepted proposal

def on_prepare(n):
    global promised
    if n > promised:
        promised = n
        return ("promise", n, accepted)
    return None     # ignore; may tell the proposer to give up

def on_accept(n, v):
    global promised, accepted
    if n >= promised:   # not promised to a higher number
        promised = n
        accepted = (n, v)
        return ("accepted", n, v)
    return None

def choose_value(promises, my_value):
    # proposer, after promises from a majority
    prior = [a for (_, _, a) in promises if a is not None]
    if prior:
        return max(prior)[1]   # value of highest-numbered one
    return my_value

